<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue';import { ElMessageBox } from 'element-plus';import { notesApi } from '@/api/modules';import type { StudyNote } from '@/types'
const rows=ref<StudyNote[]>([]),loading=ref(false),preview=ref<StudyNote|null>(null);const query=reactive({tag:'',keyword:'',page:1,pageSize:20})
async function load(){loading.value=true;try{rows.value=(await notesApi.list(query)).records}finally{loading.value=false}}async function del(id:number){await ElMessageBox.confirm('确认删除这篇笔记？','删除笔记',{type:'warning'});await notesApi.remove(id);if(preview.value?.id===id)preview.value=null;load()}onMounted(load)
</script>
<template><section class="workspace"><header class="page-head"><div><h1>学习笔记</h1><p>浏览、检索与预览已有学习内容</p></div></header><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="搜索标题或内容" class="max-w-64" @keyup.enter="load"/><el-input v-model="query.tag" clearable placeholder="标签" class="max-w-36"/><el-button @click="load">筛选</el-button></div><div class="notes-layout"><div v-loading="loading" class="note-list"><button v-for="note in rows" :key="note.id" type="button" :class="{active:preview?.id===note.id}" @click="preview=note"><span><el-tag size="small" effect="plain">{{note.tag}}</el-tag><time>{{new Date(note.updatedAt).toLocaleDateString('zh-CN')}}</time></span><strong>{{note.title}}</strong><p>{{note.markdownBody.replace(/[#*`>-]/g,'').slice(0,90)}}</p></button><el-empty v-if="!loading&&!rows.length" description="暂无学习笔记"/></div><article class="preview surface"><template v-if="preview"><header><div><el-tag effect="plain">{{preview.tag}}</el-tag><h2>{{preview.title}}</h2></div><el-button type="danger" link @click="del(preview.id)">删除</el-button></header><pre>{{preview.markdownBody}}</pre></template><el-empty v-else description="选择左侧笔记进行预览"/></article></div></section></template>
<style scoped>.notes-layout{display:grid;grid-template-columns:minmax(260px,360px) 1fr;gap:20px;min-height:520px}.note-list{display:grid;align-content:start;gap:8px}.note-list button{width:100%;padding:17px;text-align:left;border:1px solid transparent;border-radius:12px;background:transparent;cursor:pointer;transition:.18s}.note-list button:hover,.note-list button.active{background:var(--paper);border-color:var(--line);box-shadow:0 8px 24px rgba(32,51,44,.05)}.note-list button>span{display:flex;justify-content:space-between;align-items:center}.note-list time{color:var(--muted);font-size:11px}.note-list strong{display:block;margin:12px 0 7px;font:600 17px Georgia,"Songti SC",serif}.note-list p{margin:0;color:var(--muted);font-size:12px;line-height:1.5}.preview{padding:30px}.preview header{display:flex;justify-content:space-between}.preview h2{margin:12px 0 24px;font:600 28px Georgia,"Songti SC",serif}.preview pre{white-space:pre-wrap;word-break:break-word;font:14px/1.9 "Microsoft YaHei",sans-serif;color:#394a43}@media(max-width:800px){.notes-layout{grid-template-columns:1fr}.preview{min-height:320px}}</style>
